# Let's verify K_{5,5} is maximal triangle-free
n = 10
A = {0,1,2,3,4}
B = {5,6,7,8,9}
edges = [(u,v) for u in A for v in B]
print("Number of edges:", len(edges))

# Check triangle-free
adj = {i: set() for i in range(n)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

triangle = False
for u in range(n):
    for v in adj[u]:
        if v > u:
            for w in adj[v]:
                if w > v and w in adj[u]:
                    triangle = True
                    print("Triangle found:", u, v, w)
print("Triangle-free:", not triangle)

# Check maximal: for every non-edge, adding it creates a triangle
non_edges = [(u,v) for u in range(n) for v in range(u+1, n) if v not in adj[u]]
print("Number of non-edges:", len(non_edges))
maximal = True
for u,v in non_edges:
    # Check if there exists w adjacent to both u and v
    common = adj[u].intersection(adj[v])
    if not common:
        maximal = False
        print("Non-edge", u, v, "can be added without creating triangle")
        break
print("Maximal:", maximal)

print("Edges:", edges)
